INSERT INTO "policy_chunks" VALUES('C1','RTE10','Rule 6(1)(a)','In respect of children in classes from I to V, a school shall be established within a walking distance of one km of the neighbourhood.','walking distance one km primary neighbourhood access',1);
INSERT INTO "policy_chunks" VALUES('C2','RTE10','Rule 6(1)(b)','In respect of children in classes from VI to VIII, a school shall be established within a walking distance of three km of the neighbourhood.','walking distance three km upper primary middle',1);
INSERT INTO "policy_chunks" VALUES('C3','RTE10','Rule 6(3)','In places with difficult terrain, risk of landslides, floods, lack of roads and in general, danger for young children in the approach from their homes to the school, the appropriate Government or the local authority shall locate the school in such a manner as to avoid such dangers, by reducing the area or limits specified.','difficult terrain landslide flood roads danger young children route bridge river seasonal',0);
INSERT INTO "policy_chunks" VALUES('C4','RTE10','Rule 6(4)','For children from small hamlets, where no school exists within the area or limits of neighbourhood, the appropriate Government or the local authority shall make adequate arrangements, such as free transportation and residential facilities, for providing elementary education.','small hamlets habitation free transportation transport residential arrangements distance',0);
INSERT INTO "policy_chunks" VALUES('C5','RTE10','Rule 6(7)','In respect of children with disabilities, the appropriate Government or the local authority shall endeavour to make appropriate and safe transportation arrangements.','disabilities cwsn safe transportation transport',0);
INSERT INTO "policy_chunks" VALUES('C6','SSN','Transport / escort facility','Provision for transport / escort facility up to secondary level for children in remote habitations with sparse population, where opening of schools is unviable or where Gross Access Ratio is low. Transport facility may be provided up to an average cost @ Rs. 6000 per child per annum up to Class X. This would be appraised based on actual cost to be incurred as per the distance, the terrain and the type of transport facility.','transport escort facility remote habitation sparse cost 6000 per child per annum terrain distance vehicle',1);
INSERT INTO "policy_chunks" VALUES('C7','SSN','Transport / escort facility — DBT','The option of cash transfer will be allowed in the form of DBT to Aadhaar-linked bank accounts, linked to the actual attendance.','cash transfer dbt attendance transport allowance',1);
INSERT INTO "policy_chunks" VALUES('C8','SSN','Residential schools / hostels','Support for reaching out to children in sparsely populated, or hilly and densely forested areas with difficult geographical terrain and border areas where opening of new primary or upper primary school may not be viable.','residential hostel hilly terrain sparse forested',0);
INSERT INTO "policy_chunks" VALUES('C9','HP25','Merger criteria, primary','Primary schools with fewer than five students are to be merged within a 2 km radius; where no other school exists within that range, the merger distance is extended to 3 km. (Announced 7 June 2025; 103 zero-enrolment schools closed, 443 low-enrolment schools merged.)','merger radius 2 km 3 km primary enrolment five',0);
INSERT INTO "policy_chunks" VALUES('C10','NEP20','School complexes','Schools are to be grouped into school complexes: one secondary school with other schools and anganwadis within a 5–10 km radius, to share teachers and resources.','school complex cluster 5 10 km radius sharing resources',0);
INSERT INTO "policy_chunks" VALUES('C11','HCS26','Judgment on distance','The High Court upheld the merger of GMS Sandyar into GSSS Chhat, noting 1.5 km by road and about 500 m on foot, and indicated it would intervene where distance made access difficult.','court distance access merger upheld walking',0);
