CREATE TABLE answers (
  group_id TEXT, kind TEXT, choice TEXT, note TEXT, answered_on TEXT, source TEXT,
  PRIMARY KEY (group_id, kind));
CREATE TABLE attendance (group_id TEXT, month TEXT, school_id TEXT, pct REAL, source TEXT);
CREATE TABLE budget (item TEXT, district TEXT, amount_inr INTEGER, note TEXT, source TEXT);
CREATE TABLE citizen_feedback (fb_id INTEGER PRIMARY KEY, school_id TEXT, about_id TEXT, hab_id TEXT, theme TEXT, text_hi TEXT, text_en TEXT,
      channel TEXT, received TEXT, sender_role TEXT, status TEXT, verified_by TEXT, source TEXT);
CREATE TABLE feedback (
  feedback_id INTEGER PRIMARY KEY, group_id TEXT, received TEXT, channel TEXT, language TEXT,
  sender_role TEXT, text_original TEXT, text_en TEXT, issue TEXT, severity TEXT,
  sentiment TEXT, verification TEXT, verified_by TEXT, source TEXT, based_on TEXT);
CREATE TABLE field_obs (obs_id TEXT PRIMARY KEY, feature_id TEXT, school_id TEXT, kind TEXT, text TEXT, observed_by TEXT,
      observed_on TEXT, status TEXT, source TEXT, source_url TEXT);
CREATE TABLE geo_features (feature_id TEXT PRIMARY KEY, kind TEXT, name TEXT, geometry TEXT, season TEXT, detail TEXT,
      status TEXT, source TEXT, source_url TEXT);
CREATE TABLE habitations (hab_id TEXT PRIMARY KEY, name TEXT, school_id TEXT, lat REAL, lng REAL, elev_m INTEGER,
      road_connected INTEGER, source TEXT);
CREATE TABLE hazards (
  hazard_id INTEGER PRIMARY KEY, group_id TEXT, kind TEXT, label TEXT, months TEXT,
  month_list TEXT, severity TEXT, data_source TEXT, source TEXT);
CREATE TABLE implementation (group_id TEXT, code TEXT, status TEXT, note TEXT, updated_on TEXT, source TEXT,
  PRIMARY KEY (group_id, code));
CREATE TABLE links (from_id TEXT, to_id TEXT, road_km REAL, road_min INTEGER, walk_km REAL, climb_m INTEGER, descent_m INTEGER,
      route_walk TEXT, route_road TEXT, source TEXT, note TEXT, PRIMARY KEY (from_id, to_id));
CREATE TABLE merge_groups (
  group_id TEXT PRIMARY KEY, sending_id TEXT, receiving_id TEXT, district TEXT, block TEXT,
  status TEXT, status_detail TEXT, order_date TEXT, source TEXT, source_url TEXT, created_by TEXT,
  merge_id TEXT);
CREATE TABLE policy_chunks (chunk_id TEXT PRIMARY KEY, doc_id TEXT, section TEXT, text TEXT, keywords TEXT, verbatim INTEGER);
CREATE TABLE policy_docs (doc_id TEXT PRIMARY KEY, title TEXT, issuer TEXT, year TEXT, url TEXT, source TEXT);
CREATE TABLE precedents (
  precedent_id INTEGER PRIMARY KEY, case_name TEXT, state TEXT, year TEXT,
  pattern TEXT, outcome TEXT, url TEXT);
CREATE TABLE routes (
  group_id TEXT PRIMARY KEY, straight_km REAL, walk_km REAL, walk_min INTEGER,
  climb_m INTEGER, road_km REAL, source TEXT, source_note TEXT);
CREATE TABLE rules (
  rule_id TEXT PRIMARY KEY, name TEXT, statement TEXT, param_name TEXT,
  param_value REAL, unit TEXT, reference TEXT, url TEXT);
CREATE TABLE school_facts (school_id TEXT PRIMARY KEY, building TEXT, rooms_good INTEGER, rooms_minor INTEGER, rooms_major INTEGER,
      toilets_girls INTEGER, toilets_boys INTEGER, cwsn_toilets INTEGER, ramp INTEGER, handrails INTEGER, drinking_water INTEGER,
      electricity INTEGER, all_weather_road INTEGER, enrol_girls INTEGER, enrol_boys INTEGER, cwsn INTEGER, transport_students INTEGER,
      established INTEGER, cluster TEXT, source TEXT, source_note TEXT, source_url TEXT);
CREATE TABLE school_terrain (school_id TEXT PRIMARY KEY, terrain TEXT, elev_m INTEGER, slope_pct INTEGER,
      crossing_kind TEXT, crossing_name TEXT, monsoon_hazard TEXT, monsoon_note TEXT, snow_months TEXT, road_type TEXT, wildlife TEXT,
      source TEXT, note TEXT);
CREATE TABLE schools (
  school_id TEXT PRIMARY KEY, udise_code TEXT, name TEXT, level TEXT, level_code TEXT,
  district TEXT, block TEXT, village TEXT, lat REAL, lng REAL, loc_note TEXT,
  enrol_total INTEGER, enrol_primary INTEGER, enrol_preprimary INTEGER,
  teachers INTEGER, classrooms INTEGER, anganwadi_on_site INTEGER,
  source TEXT, source_note TEXT);
CREATE TABLE surveys (survey_id INTEGER PRIMARY KEY, merge_id TEXT, group_id TEXT, field TEXT, value TEXT,
  agent TEXT, done_on TEXT);